import TodaysWeather from "./components/TodaysWeather/TodaysWeather";
import WeeklyWeather from "./components/WeeklyWeather/WeeklyWeather";

import "./App.css";

function App() {
  return (
    <div>
      <form onSubmit={(e)=>input()}>
        <input type="text" />
        <input type="submit"/>
      </form>
      <TodaysWeather />
      <WeeklyWeather />
    </div>
  );
}

export default App;
